const module = angular
	.module("irtech.netcity.school.addservices",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"netcity.common.menu", "ngFileUpload", "ui.tree", "irtech.netcity.common", "irtech.netcity.ui-components"
	]);


require("./repository.js");
require("./list/addServicesListCtrl.js");
require("./edit/editAddServiceCtrl.js");


module
.config(($routeProvider, $locationProvider) => {
	$routeProvider
		.when("/list", {
			templateUrl: "/static/dist/app/school/addservices/list/template.html",
			controller: "AddServiceListCtrl"
		})
		.otherwise({
			templateUrl: "/static/dist/app/school/addservices/list/template.html",
			controller: "AddServiceListCtrl"
		});

	$locationProvider.hashPrefix('');
	$locationProvider.html5Mode({
		enabled: true,
		requireBase: true
	});
});



