"use strict";

import Selectable from "approot/global/selectable.js";
import * as AddServicesRefs from "approot/school/addservices/refs.js";

angular
	.module("irtech.netcity.school.addservices")

	.controller("EditAddServiceCtrl",
		($scope, addServicesRepository, $http, $q, $alerts, $routeParams, $dialogs, $appLoader, $uibModal, $uibModalInstance, addService, mode) => {

			$.extend($scope, {
				language: language,
				data: {
					addService: addService,
					selection: new Selectable(),
					addServiceTypes: AddServicesRefs.default.addServicesTypes
				},
				state: {
					dataReady: false,
					emptyData: false,
					viewReady: true,
					contentWasChanged: false
				},
				mode: mode,
				header: mode.edit ? "Редактировать дополнительную услугу" : "Добавить дополнительную услугу"
			});

			$scope.cancel = () => {
				$uibModalInstance.dismiss("cancel");
			};

			$scope.save = (valid, addService) => {
				if (valid) {
					if (addService) {
						addServicesRepository.edit(addService)
							.then((addService) => {
								$scope.state.dataReady = true;
								$appLoader.hide();
								$uibModalInstance.close(addService);
							});
					} 
					else {
						addServicesRepository.create($scope.data.addService.item).then((addService) => {
							$appLoader.hide();
							if (addService) {
								$scope.state.dataReady = true;
								$scope.mode.edit = true;
								$scope.mode.create = false;
								$scope.data.addService.item = addService;
								$uibModalInstance.close(addService);
							}
						});
					}
				}
			}

			$scope.load = () => {
				addServicesRepository.getStaffList(appContext.yearId, $scope.data.addService ? $scope.data.addService.item : null)
					.then((staffList) => {
						$scope.data.users = staffList;
						$appLoader.hide();
					});
			}

			$scope.load();


		});


