"use strict";

import { BaseRepository } from "approot/global/repository.js";

class AddServicesRepository extends BaseRepository {
	getAll(params) {
		params = params || {};
		params.yearId = appContext.yearId;
		return this.$http.get("/webapi/addServices/school", { params }).then((response) => {
			const addServices = response.data;
			if (response.headers("count")) {
				addServices.totalcount = parseInt(response.headers("count"));
			}
			return addServices;
		});
	}

	getStaffList(yearId, addService) {
		var params = {};
		params.yearId = yearId;
		params.userId = addService && addService.user ? addService.user.id : -1;
		return this.$http.get("/webapi/addServices/staff", { params }).then((response) => {
			return response.data;
		});
	}


	create(service) {
		service.schoolYearId = appContext.yearId;
		return this.$http.post(`/webapi/addServices`, service)
			.then((response) => {
				this.$alerts.success("Добавлена новая дополнительная услуга");
				return response.data;
			})
			.catch(this.handleError);
	}

	remove(id) {
		return this.$http.delete(`/webapi/addServices?addServiceId=${id}`)
			.then(() => { this.$alerts.success("Дополнительная услуга удалена"); })
			.catch(this.handleError);
	}

	edit(service) {
		return this.$http.put("/webapi/addServices", service)
			.then((response) => {
				this.$alerts.success("Дополнительная услуга отредактирована");
				return response.data;
			})
			.catch(this.handleError);
	}
}


angular
	.module("irtech.netcity.school.addservices")
	.factory('addServicesRepository', ($http, $dialogs, $alerts) => new AddServicesRepository($http, $dialogs, $alerts))
;


