class Selectable {
	constructor() {
		this.item = null;

		Object.defineProperty(this,
			"selected",
			{
				get: () => { return this.item; },
				set: (val) => { this.item = val; }
			}
		);
	}

	isSelected(val) {
		return this.item === val;
	}

	select(val) {
		if (val === this.item) {
			this.item = null;
		} else {
			this.item = val;
		}
	}

	dropSelect() {
		this.item = null;
	}
}

module.exports = Selectable


