"use strict";

import Selectable from "approot/global/selectable.js";

angular
	.module("irtech.netcity.school.addservices")
	.controller("AddServiceListCtrl",
		($scope, $http, $q, $alerts, $routeParams, $dialogs, $appLoader, $uibModal, addServicesRepository) => {

			$scope.$parent.page = {
				title: "Дополнительные услуги"
			}

			angular.extend($scope,
			{
				paging: {
					page: 1,
					pageSize: 20,
					totalcount: 0
				}
			});

			$.extend($scope,
			{
				language: language,
				data: {
					addServices: [],
					selection: new Selectable()
				},
				state: {
					dataReady: false,
					emptyData: false,
					viewReady: true,
					readOnlyContext: appContext.readOnly
				}
			});

			//редактировать
			$scope.editService = (addService) => {
				let modalInstance = $uibModal.open({
					templateUrl: '/static/dist/app/school/addservices/edit/template.html',
					controller: 'EditAddServiceCtrl',
					backdrop: false,
					resolve: {
						addService: () => angular.copy(addService),
						mode: () => new Object({ edit: true })
					}
				});
				modalInstance.result.then(() => $scope.load());
				modalInstance.closed.then(() => $scope.load());
			}

			//добавить
			$scope.addService = (addService) => {
				let modalInstance = $uibModal.open({
					templateUrl: '/static/dist/app/school/addservices/edit/template.html',
					controller: 'EditAddServiceCtrl',
					backdrop: false,
					resolve: {
						addService: addService,
						mode: () => new Object({ create: true })
					}
				});
				modalInstance.result.then((addService) => $scope.load());
				modalInstance.closed.then(() => $scope.load());
			}

			//удалить
			$scope.removeService = (addService) => {
				$.show.confirmation(`Удалить дополнительную услугу "${addService.name}"?`.escapeHTML())
					.then(function() {
						addServicesRepository.remove(addService.id)
							.then(() => {
								$scope.load();
							});
					});
			};

			//загрузка данных
			$scope.load = () => {
				const params = {
					page: $scope.paging.page,
					pageSize: $scope.paging.pageSize
				};
				addServicesRepository.getAll(params)
					.then((addServices) => {
						// paging
						$scope.paging.totalcount = addServices.totalcount;
						$scope.paging.show = $scope.paging.totalcount > $scope.paging.pageSize && $scope.paging.page > 0;

						$scope.data.addServices = addServices;
						$scope.data.selection.selected = false;
						$scope.state.emptyData = !addServices.length;
						$scope.state.dataReady = true;
						$appLoader.hide();
					});
			}

			$scope.load();
		});



